#!/usr/bin/env bash
# IKS Website — รูปเพิ่มเติม (สไลด์) ของประเภทธุรกิจ 4 หมวด · ต้องติดตั้งเว็บ v6 ก่อน · รันซ้ำได้
if [ "${BASH_SOURCE[0]:-$0}" != "$0" ]; then echo "กรุณารันด้วย: bash ${BASH_SOURCE[0]}"; return 1 2>/dev/null || exit 1; fi
set -euo pipefail
SELF="$(readlink -f "$0")"
DEST=/var/www/ikssa-media/industries
mkdir -p "$DEST"
sed -n '/^__ARCHIVE_BELOW__$/,$p' "$SELF" | tail -n +2 | base64 -d | tar -xz --no-same-owner -C "$DEST"
chmod 755 "$DEST"; chmod 644 "$DEST"/*.webp
echo "✔ คัดลอกรูปเพิ่มเติมแล้ว"
docker exec -i iks-web-db psql -q -U iks_owner -d iks_web -v ON_ERROR_STOP=1 <<'SQL'
begin;
insert into public.media_files (path, original_name, mime_type, size_bytes, width, height, alt_text) values
  ('industries/industry-logistics-2.webp', 'industry-logistics-2.webp', 'image/webp', 101616, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ โลจิสติกส์'),
  ('industries/industry-logistics-3.webp', 'industry-logistics-3.webp', 'image/webp', 92672, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ โลจิสติกส์'),
  ('industries/industry-cold-2.webp', 'industry-cold-2.webp', 'image/webp', 94908, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ ห้องเย็น'),
  ('industries/industry-food-bakery.webp', 'industry-food-bakery.webp', 'image/webp', 120668, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ ธุรกิจอาหาร'),
  ('industries/industry-food-juice.webp', 'industry-food-juice.webp', 'image/webp', 104350, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ ธุรกิจอาหาร'),
  ('industries/industry-construction-2.webp', 'industry-construction-2.webp', 'image/webp', 112782, 1200, 900, 'รถอีซูซุสำหรับธุรกิจ ก่อสร้าง')
on conflict (path) do nothing;
update public.industries set gallery = '["industries/industry-logistics-2.webp", "industries/industry-logistics-3.webp"]'::jsonb where name = 'โลจิสติกส์' and gallery = '[]'::jsonb;
update public.industries set gallery = '["industries/industry-cold-2.webp"]'::jsonb where name = 'ห้องเย็น' and gallery = '[]'::jsonb;
update public.industries set gallery = '["industries/industry-food-bakery.webp", "industries/industry-food-juice.webp"]'::jsonb where name = 'ธุรกิจอาหาร' and gallery = '[]'::jsonb;
update public.industries set gallery = '["industries/industry-construction-2.webp"]'::jsonb where name = 'ก่อสร้าง' and gallery = '[]'::jsonb;
commit;
\pset footer off
select name as "ประเภท", status as "สถานะ", (case when image is null then 0 else 1 end) + jsonb_array_length(gallery) as "จำนวนรูป" from public.industries order by sort_order;
SQL
echo; echo "✔ เสร็จแล้ว — ดูได้ที่ https://ikssa.io/admin/preview?to=/commercial"
exit 0
